updated def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (2, 9)]
    if not points:
        return out
    line_c = max(c for r, c in points) + 1
    if line_c < len(grid[0]):
        for r in range(len(grid)):
            out[r][line_c] = 8
    return out
